import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ValidarURL {
    public static void main(String[] args) {
        String[] urls = {
            "https://www.google.com",
            "http://ejemplo.com/pagina",
            "ftp://invalido.com",
            "https://",
            "https://www.ejemplo.com.co/ruta/sub"
        };

        Pattern patron = Pattern.compile("https?://[a-zA-Z0-9.-]+\\.[a-zA-Z]{2,}(/.*)*");

        for (String url : urls) {
            Matcher matcher = patron.matcher(url);
            System.out.println(url + " => " + matcher.matches());
        }
    }
}
